// Builds paste-ready SQL for the Supabase Dashboard SQL Editor (no CLI needed):
//   supabase/sql/01_setup.sql                 all migrations + required reference data (courses, branches)
//   supabase/sql/02_demo_content_optional.sql sample videos & portfolios, inserted HIDDEN (for testing only)
//   supabase/sql/upgrades/<migration>.sql     one migration each — for projects already set up earlier
// Usage: node scripts/build-sql-bundle.js   (re-run whenever a migration changes)
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const migDir = path.join(root, 'supabase/migrations');
const outDir = path.join(root, 'supabase/sql');
fs.mkdirSync(outDir, { recursive: true });

const migrations = fs.readdirSync(migDir).filter((f) => f.endsWith('.sql')).sort();
const seed = fs.readFileSync(path.join(root, 'supabase/seed.sql'), 'utf8');

// seed.sql = blank-line separated statements; split them by target table.
const blocks = seed.split(/\n\s*\n/).map((b) => b.trim()).filter((b) => b.startsWith('insert into'));
const pick = (table) => blocks.filter((b) => b.startsWith(`insert into public.${table} `));
const reference = [...pick('categories'), ...pick('branches')];
const demo = [...pick('videos'), ...pick('portfolios')];
if (reference.length !== 2 || demo.length !== 2) throw new Error('Unexpected seed.sql layout');

const versions = migrations.map((f) => f.split('_')[0]);

const setup = `-- ═══════════════════════════════════════════════════════════════════════════
-- TH EDU Companion — full database setup (generated by scripts/build-sql-bundle.js — do not edit)
--
-- HOW TO RUN: Supabase Dashboard → project → SQL Editor → New query → paste this whole file → Run.
-- Run ONCE on a fresh project. It is wrapped in a transaction: if anything fails, nothing is applied.
--
-- Includes migrations: ${migrations.join(', ')}
-- plus required reference data (course categories, branches).
--
-- If you later switch to the Supabase CLI (supabase db push), first mark these as applied:
--   npx supabase migration repair --status applied ${versions.join(' ')}
-- ═══════════════════════════════════════════════════════════════════════════

begin;

${migrations
  .map((f) => `-- ───────────────── ${f} ─────────────────\n${fs.readFileSync(path.join(migDir, f), 'utf8').trim()}\n`)
  .join('\n')}
-- ───────────────── Reference data (required) ─────────────────
${reference.join('\n\n')}

commit;

-- Done. Next: create staff accounts (supabase/README.md → "Staff accounts").
`;

const demoSql = `-- ═══════════════════════════════════════════════════════════════════════════
-- OPTIONAL demo content (generated by scripts/build-sql-bundle.js — do not edit)
--
-- 8 sample videos (stock clips) + 6 FICTIONAL student portfolios, for testing the app.
-- Everything is inserted HIDDEN: parents see none of it.
--   • Videos: publish individually from the app's "Quản lý video" if you really want to.
--   • Portfolios are fictional children — never publish them. Replace with real, consented ones.
-- Run AFTER 01_setup.sql. To remove later:
--   delete from public.videos where video_url like 'https://commondatastorage.googleapis.com/%';
--   delete from public.portfolios where before_image_url like 'https://picsum.photos/%';
-- ═══════════════════════════════════════════════════════════════════════════

begin;

${demo.join('\n\n')}

-- Keep all demo content hidden.
update public.videos set is_published = false where video_url like 'https://commondatastorage.googleapis.com/%';
update public.portfolios set is_published = false, parent_consent = false where before_image_url like 'https://picsum.photos/%';

commit;
`;

fs.writeFileSync(path.join(outDir, '01_setup.sql'), setup);
fs.writeFileSync(path.join(outDir, '02_demo_content_optional.sql'), demoSql);
console.log(`01_setup.sql: ${migrations.length} migrations + ${reference.length} reference inserts (${setup.length} chars)`);
console.log(`02_demo_content_optional.sql: ${demo.length} inserts, all hidden`);

// Upgrades: an existing project only needs the migrations added since it was set up.
const upDir = path.join(outDir, 'upgrades');
fs.mkdirSync(upDir, { recursive: true });
for (const f of migrations) {
  const body = `-- Upgrade: ${f}  (generated by scripts/build-sql-bundle.js — do not edit)
-- For a project that was set up BEFORE this migration existed. Run each upgrade once, in date order:
-- Dashboard → SQL Editor → paste → Run. Atomic: on error nothing is applied.
-- (A fresh project only needs 01_setup.sql, which already contains this.)

begin;

${fs.readFileSync(path.join(migDir, f), 'utf8').trim()}

commit;
`;
  fs.writeFileSync(path.join(upDir, f), body);
}
console.log(`upgrades/: ${migrations.length} files`);
